  "      response = syncAll(payload, authUser);",
  "    }",
  "    else if (action === \u0027batchMutations\u0027 || action === \u0027batch\u0027) {",
  "      response = handleBatchMutations(payload, authUser);",
  "    }",
  "    ",
  "    // Inventory",
  "    else if (action === \u0027getInventory\u0027) response = { success: true, data: readSheetRows(SHEETS.INVENTORY) };",
  "    else if (action === \u0027saveInventory\u0027) response = writeSheetRow(SHEETS.INVENTORY, payload, \u0027ID\u0027, authUser);",
  "    else if (action === \u0027deleteInventory\u0027 || action === \u0027deleteInventoryItem\u0027) response = deleteSheetRow(SHEETS.INVENTORY, extractId(payload), \u0027ID\u0027, authUser, payload \u0026\u0026 payload._mutationId);",
  "",
  "    // Sales",
  "    else if (action === \u0027getSales\u0027) response = { success: true, data: readSheetRows(SHEETS.SALES) };",
  "    else if (action === \u0027saveSale\u0027) response = writeSheetRow(SHEETS.SALES, payload, \u0027ID\u0027, authUser);",
  "    else if (action === \u0027deleteSale\u0027 || action === \u0027deleteSaleRecord\u0027) response = deleteSheetRow(SHEETS.SALES, extractId(payload), \u0027ID\u0027, authUser, payload \u0026\u0026 payload._mutationId);",
  "",
  "    // Outlets",
  "    else if (action === \u0027getOutlets\u0027) response = { success: true, data: readSheetRows(SHEETS.OUTLETS) };",
  "    else if (action === \u0027saveOutlet\u0027) response = writeSheetRow(SHEETS.OUTLETS, payload, \u0027ID\u0027, authUser);",
  "    else if (action === \u0027deleteOutlet\u0027) response = deleteSheetRow(SHEETS.OUTLETS, extractId(payload), \u0027ID\u0027, authUser, payload \u0026\u0026 payload._mutationId);",
  "",
  "    // Dispatches",
  "    else if (action === \u0027getDispatches\u0027) response = { success: true, data: readSheetRows(SHEETS.DISPATCH) };",
  "    else if (action === \u0027saveDispatch\u0027) response = writeSheetRow(SHEETS.DISPATCH, payload, \u0027ID\u0027, authUser);",
  "    else if (action === \u0027deleteDispatch\u0027 || action === \u0027deleteDispatchLoad\u0027) response = deleteSheetRow(SHEETS.DISPATCH, extractId(payload), \u0027ID\u0027, authUser, payload \u0026\u0026 payload._mutationId);",
  "",
  "    // Cash Slips",
