  "    else if (action === \u0027saveCashSlip\u0027) response = writeSheetRow(SHEETS.CASH_SLIPS, payload, \u0027id\u0027, authUser);",
  "    else if (action === \u0027deleteCashSlip\u0027) response = deleteSheetRow(SHEETS.CASH_SLIPS, extractId(payload), \u0027id\u0027, authUser, payload \u0026\u0026 payload._mutationId);",
  "",
  "    // Payments",
  "    else if (action === \u0027getPayments\u0027) response = { success: true, data: readSheetRows(SHEETS.PAYMENTS) };",
  "    else if (action === \u0027savePayment\u0027) response = writeSheetRow(SHEETS.PAYMENTS, payload, \u0027ID\u0027, authUser);",
  "    else if (action === \u0027deletePayment\u0027) response = deleteSheetRow(SHEETS.PAYMENTS, extractId(payload), \u0027ID\u0027, authUser, payload \u0026\u0026 payload._mutationId);",
  "",
  "    // Closings",
  "    else if (action === \u0027getClosings\u0027) response = { success: true, data: readSheetRows(SHEETS.CLOSINGS) };",
  "    else if (action === \u0027saveClosing\u0027) response = writeSheetRow(SHEETS.CLOSINGS, payload, \u0027ID\u0027, authUser);",
  "",
  "    // Stock Inward",
  "    else if (action === \u0027getStockInward\u0027) response = { success: true, data: readSheetRows(SHEETS.STOCK_INWARD) };",
  "    else if (action === \u0027saveStockInward\u0027) response = writeSheetRow(SHEETS.STOCK_INWARD, payload, \u0027ID\u0027, authUser);",
  "",
  "    // Movements",
  "    else if (action === \u0027getStockMovements\u0027) response = { success: true, data: readSheetRows(SHEETS.STOCK_MOVEMENTS) };",
  "    else if (action === \u0027saveStockMovement\u0027) response = writeSheetRow(SHEETS.STOCK_MOVEMENTS, payload, \u0027ID\u0027, authUser);",
  "",
  "    // Routes",
  "    else if (action === \u0027getRoutes\u0027) response = { success: true, data: readSheetRows(SHEETS.ROUTES) };",
  "    else if (action === \u0027saveRoute\u0027) response = writeSheetRow(SHEETS.ROUTES, payload, \u0027ID\u0027, authUser);",
  "    else if (action === \u0027deleteRoute\u0027) response = deleteSheetRow(SHEETS.ROUTES, extractId(payload), \u0027ID\u0027, authUser, payload \u0026\u0026 payload._mutationId);",
  "",
  "    // Users",
  "    else if (action === \u0027getUsers\u0027) response = { success: true, data: readSheetRows(SHEETS.USERS) };",
  "    else if (action === \u0027saveUser\u0027) response = writeSheetRow(SHEETS.USERS, payload, \u0027id\u0027, authUser);",
  "    else if (action === \u0027deleteUser\u0027) response = deleteSheetRow(SHEETS.USERS, extractId(payload), \u0027id\u0027, authUser, payload \u0026\u0026 payload._mutationId);",
  "",
  "    // Order Bookers",
  "    else if (action === \u0027getOrderBookers\u0027) response = { success: true, data: readSheetRows(SHEETS.ORDER_BOOKERS) };",
  "    else if (action === \u0027saveOrderBooker\u0027) response = writeSheetRow(SHEETS.ORDER_BOOKERS, payload, \u0027ID\u0027, authUser);",
  "    else if (action === \u0027deleteOrderBooker\u0027) response = deleteSheetRow(SHEETS.ORDER_BOOKERS, extractId(payload), \u0027ID\u0027, authUser, payload \u0026\u0026 payload._mutationId);",
  "",
  "    // Delivery Men",
  "    else if (action === \u0027getDeliveryMen\u0027) response = { success: true, data: readSheetRows(SHEETS.DELIVERY_MEN) };",
  "    else if (action === \u0027saveDeliveryMan\u0027) response = writeSheetRow(SHEETS.DELIVERY_MEN, payload, \u0027ID\u0027, authUser);",
  "    else if (action === \u0027deleteDeliveryMan\u0027) response = deleteSheetRow(SHEETS.DELIVERY_MEN, extractId(payload), \u0027ID\u0027, authUser, payload \u0026\u0026 payload._mutationId);",
  "",
  "    // Audit Logs",
  "    else if (action === \u0027getAuditLogs\u0027) response = { success: true, data: readSheetRows(SHEETS.AUDIT) };",
  "    else if (action === \u0027saveAuditLog\u0027) response = writeSheetRow(SHEETS.AUDIT, payload, \u0027Timestamp\u0027, authUser);",
  "",
  "    // 9. Log Successful State Mutation",
  "    if (isWrite \u0026\u0026 response \u0026\u0026 response.success) {",
  "      logAuditTrail(authUser.uid, authUser.email, authUser.role, action, extractId(payload), \u0027SUCCESS\u0027, \u0027Row mutation committed\u0027, appCheckToken);",
  "    }",
  "",
  "    return createJsonResponse(response);",
  "",
  "  } catch (err) {",
  "    Logger.log(\u0027Error in handleRequest: \u0027 + err.toString());",
  "    return createJsonResponse({",
  "      success: false,",
  "      status: 500,",
  "      error: \u0027An internal server error occurred. Request could not be processed.\u0027",
  "    });",
  "  } finally {",
  "    flushRequestState_();",
  "  }",
  "}",
